/**
 * Bug 443 —— 侧车注释里**提到** `@generated` 这个词 ⇒ 手写段被判成生成段 ⇒
 * `nudo contract --emit --all` **直接覆盖用户手写契约**（数据丢失：手写的
 * `fn({ x: number().gt(0) })` 被换成观测值冻结的 `lit(-1)` / `lit(0)`）。
 *
 * 根因：「是不是 nudo 生成的段」由**裸子串**判定，而 nudo 自己的提示语里就含有
 * `@generated` 这个词 ⇒ 用户在注释里**引用**这句话（正面或反面）就会被误判 ⇒
 * emit 侧的「保留手写段」保护（`handwrittenNames` / `declared`）失效。
 *
 * 本文件钉住两件事：
 * ① **产品面**：侧车里只有散文提及 `@generated` 时，`--emit` **不得**覆盖手写
 *    契约（`nudo:interface-name-clash` + 跳过）。
 * ② **跨包一致性**：core 的 `generatedExportNames` 与 service 侧（派生路径
 *    `interface-derivation-emit.ts` + 主路径 `interface-emitter.ts`）对同一份
 *    侧车源码的「谁是生成段」判定必须一致（core / service 两份实现同批落地）。
 */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, writeFileSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { generatedExportNames } from "@nudojs/core";
import { emitInterface } from "../interface-emitter.ts";

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "nudo-443-"));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

const LIB_JS = `export function scale(x) {
  return x * 2;
}

scale(3);
`;

/** 侧车：注释里**提到** `@generated`，但这段是**手写**契约 */
const PROSE_SIDECAR = `import { fn, number } from "@nudojs/core";

/**
 * Handwritten contract — this is NOT a @generated block, keep it as is.
 */
export const scale = fn({ x: number().gt(0) });
`;

describe("Bug 443 — 散文提及 @generated ⇒ 手写契约不得被 emit 覆盖", () => {
  it("--emit --all 跳过手写绑定（name-clash），侧车内容原样保留", async () => {
    const file = join(dir, "lib.js");
    writeFileSync(file, LIB_JS);
    writeFileSync(join(dir, "lib.nudo.js"), PROSE_SIDECAR);
    const r = await emitInterface(file, { mode: "update", all: true });
    expect(r.skipped.map((s) => s.fn)).toContain("scale");
    expect(r.issues.some((i) => i.code === "nudo:interface-name-clash")).toBe(true);
    const after = readFileSync(join(dir, "lib.nudo.js"), "utf-8");
    expect(after).toContain("export const scale = fn({ x: number().gt(0) });");
    expect(after).not.toContain("lit(");
  });

  it("core 与 service 对「谁是生成段」的判定一致（跨包一致性）", () => {
    // core 的判定（基准）：散文提及 ⇒ 不是生成段
    expect([...generatedExportNames(PROSE_SIDECAR)]).toEqual([]);
    // service 主路径的判定（emit 侧「手写优先」保护据此生效）：同一份源码，
    // 手写段不得被当成生成段 —— 由上面的 emit 用例钉住（skipped = scale）。
    // 合法生成段：core 认得出 ⇒ service 也必须认得出（否则两面矛盾）。
    const generated = `// @generated by nudo — do not edit; regenerate with \`nudo contract --emit\`
// source: lib.js:scale
export const scale = fn({ x: number().gt(0) });
`;
    expect([...generatedExportNames(generated)]).toEqual(["scale"]);
  });

  it("合法生成段仍被识别（emit 走段替换，不报 name-clash）", async () => {
    const file = join(dir, "lib2.js");
    writeFileSync(file, LIB_JS);
    writeFileSync(
      join(dir, "lib2.nudo.js"),
      `// @generated by nudo — do not edit; regenerate with \`nudo contract --emit\`
// source: lib2.js:scale
export const scale = fn({ x: number().gt(0) });
`,
    );
    const r = await emitInterface(file, { mode: "update", all: true });
    expect(r.skipped.map((s) => s.fn)).not.toContain("scale");
    expect(r.issues.some((i) => i.code === "nudo:interface-name-clash")).toBe(false);
  });

  it("段内夹无关 const ⇒ 手写段不是生成段（Bug 432 的段边界，同批落地）", async () => {
    const file = join(dir, "lib3.js");
    writeFileSync(file, LIB_JS);
    writeFileSync(
      join(dir, "lib3.nudo.js"),
      `import { fn, number } from "@nudojs/core";
// @generated by nudo — do not edit
const helper = 1;
export const scale = fn({ x: number().gt(0) });
`,
    );
    // core 侧：手写段不是生成段
    expect([
      ...generatedExportNames(
        `import { fn, number } from "@nudojs/core";
// @generated by nudo — do not edit
const helper = 1;
export const scale = fn({ x: number().gt(0) });
`,
      ),
    ]).toEqual([]);
    const r = await emitInterface(file, { mode: "update", all: true });
    expect(r.skipped.map((s) => s.fn)).toContain("scale");
    const after = readFileSync(join(dir, "lib3.nudo.js"), "utf-8");
    expect(after).toContain("export const scale = fn({ x: number().gt(0) });");
  });
});
